+# Copyright (c) 2026 NVIDIA CORPORATION & AFFILIATES. All rights reserved.
+
+name: Publish merged unit Testmon baselines
+on:
+  push:
+    branches: [main]
+
+permissions:
+  contents: read
+  actions: read
+
+concurrency:
+  group: publish-unit-testmon-main
+  cancel-in-progress: false
+
+jobs:
+  publish:
+    if: github.repository == 'NVIDIA/Megatron-LM'
+    runs-on: ubuntu-latest
+    timeout-minutes: 20
+    steps:
+      - name: Checkout merged source
+        uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
+        with:
+          ref: ${{ github.sha }}
+      - name: Setup Python
+        uses: actions/setup-python@ece7cb06caefa5fff74198d8649806c4678c61a1 # v6
+        with:
+          python-version: '3.12'
+      - name: Install publisher dependencies
+        run: |
+          python -m pip install PyYAML
+          npm install --prefix "$RUNNER_TEMP/testmon" --no-package-lock --ignore-scripts --no-audit --no-fund \
+            @actions/cache@4.0.3 @actions/artifact@5.0.0
+      - name: Match the existing gzip cache format
+        id: compression
+        run: |
+          TESTMON_CACHE_BIN=$(mktemp -d "$RUNNER_TEMP/unit-testmon-gzip.XXXXXX")
+          printf '#!/bin/sh\nexit 1\n' > "$TESTMON_CACHE_BIN/zstd"
+          chmod +x "$TESTMON_CACHE_BIN/zstd"
+          printf 'path=%s:%s\n' "$TESTMON_CACHE_BIN" "$PATH" >> "$GITHUB_OUTPUT"
+      - name: Validate and publish merged baselines
+        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
+        env:
+          GH_TOKEN: ${{ github.token }}
+          PATH: ${{ steps.compression.outputs.path }}
+        with:
+          script: |
+            const client = `
+              (async () => {
+                const [operation, ...args] = process.argv.slice(1);
+                const modules = process.env.RUNNER_TEMP + '/testmon/node_modules/';
+                if (operation === 'download') {
+                  const {DefaultArtifactClient} = require(modules + '@actions/artifact');
+                  await new DefaultArtifactClient().downloadArtifact(Number(args[0]), {
+                    path: args[2],
+                    findBy: {
+                      token: process.env.GH_TOKEN,
+                      repositoryOwner: 'NVIDIA', repositoryName: 'Megatron-LM',
+                      workflowRunId: Number(args[1]),
+                    },
+                  });
+                } else if (operation === 'save') {
+                  const cache = require(modules + '@actions/cache');
+                  await cache.saveCache([args[0]], args[1]);
+                  const key = await cache.restoreCache([args[0]], args[1], [], {lookupOnly: true});
+                  if (key !== args[1]) throw new Error('Baseline cache publication failed');
+                } else {
+                  throw new Error('Unsupported Testmon operation: ' + operation);
+                }
+              })().catch(error => { console.error(error); process.exitCode = 1; });
+            `;
+            await exec.exec('python', ['.github/scripts/publish_unit_testmon.py'], {
+              env: {...process.env, TESTMON_NODE: process.execPath, TESTMON_ACTIONS: client},
+            });

